Q: How can I type this Axios request function properly and make it reusable using TypeScript A: <p>You can make your <code>axios</code> helper fully typed and reusable by adding generics to both the request wrapper and the calling functions by typing <code>onSuccess</code> and <code>onError</code></p>
<pre><code>import axios, {
  AxiosInstance,
  AxiosRequestConfig,
  AxiosResponse,
  AxiosError,
} from 'axios';

const client: AxiosInstance = axios.create({
  baseURL: 'http://localhost:5500/',
});

// Generic request helper
export const request = async &lt;T = unknown&gt;(
  options: AxiosRequestConfig
): Promise&lt;AxiosResponse&lt;T&gt;&gt; =&gt; {
  client.defaults.headers.common.Authorization = `Bearer Token`;

  const onSuccess = (response: AxiosResponse&lt;T&gt;): AxiosResponse&lt;T&gt; =&gt; {
    return response;
  };

  const onError = (error: AxiosError): Promise&lt;never&gt; =&gt; {
    // optionally log, redirect, etc.
    return Promise.reject(error);
  };

  return client(options).then(onSuccess).catch(onError);
};

export default client;
</code></pre>
